<?php
namespace App\Http\Controllers;
use App\Models\{CertificateTemplate,ParishSetting};use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class SettingsController extends Controller { private function data(){return ['parish'=>ParishSetting::find(1),'templates'=>CertificateTemplate::all()->keyBy('sacrament_type')];} public function show(){return response()->json(['data'=>$this->data()]);} public function preview(){return response()->json(['data'=>$this->data()]);} public function update(Request $r){ParishSetting::find(1)->update($r->only(['parish_name','diocese_name','address','default_priest_name']));return response()->json(['data'=>$this->data()]);} private function upload(Request $r,string $field,string $column){if(!$r->hasFile($field)||!$r->file($field)->isValid())return response()->json(['error'=>$field==='seal'?'Select a seal image':'No valid image uploaded'],422);$r->validate([$field=>'image|mimes:png,jpg,jpeg|max:2048']);$path=$r->file($field)->store('uploads','public');ParishSetting::find(1)->update([$column=>$path]);return response()->json(['data'=>$this->data()]);} public function uploadSeal(Request $r){return $this->upload($r,'seal','seal_image_path');} public function uploadSignature(Request $r){return $this->upload($r,'signature','priest_signature_path');} public function image(Request $r,string $type){$column=$type==='seal'?'seal_image_path':'priest_signature_path';$path=ParishSetting::find(1)?->$column;if(!$path||!Storage::disk('public')->exists($path))return response()->json(['error'=>'Image not found'],404);return response(Storage::disk('public')->get($path),200,['Content-Type'=>Storage::disk('public')->mimeType($path)]);} }
